    this.matchMediaPhone = window.matchMedia('screen and (max-width: 515px)')
    this.ephemeral.isPhone = this.matchMediaPhone.matches
    this.matchMediaPhone.onchange = (e) => {
      this.ephemeral.isPhone = e.matches
    }
  },
