      matchMediaPhone: null,
      ephemeral: {
        archivedProposals: [],
        timeouts: [],
        isPhone: false,
        isMenuOpen: false
      }
    }
  },
  computed: {
    ...mapState(['currentGroupId']),
    ...mapGetters([
      'currentGroupState',
      'currentWelcomeInvite',
      'currentIdentityState',
      'groupDistributionStarted',
      'groupShouldPropose',
      'currentGroupOwnerID',
      'ourIdentityContractId',
      'groupMembersCount'
